function firmaElectronicaCtrl(n,t,i){"use strict";let r="Config/FirmaElectronica/";n.firma={};n.fileSign=null;n.entidades=[];n.firmas=[];n.tipoOperacion=0;n.openModal=function(t=null,i){if(n.tipoOperacion=i,i==1){$("#modalFirma").modal("show");return}i==2&&(n.firma=t,n.firma.fechaCaducidad=new Date(t.fechaCaducidad),$("#modalUpdate").modal("show"))};n.initialLoad=function(){showLoader();n.firmas=[];t.getData("get",r+"Get?json="+JSON.stringify({tipo:1}),null,!0).then(function(t){if(hideLoader(),t.code==0){console.log(t);return}if(t.code=="1"){let i=JSON.parse(t.payload)[0]||[];n.firmas=i.map(n=>(n.contraseniaEncryp=n.contrasenia.replace(n.contrasenia,"*".repeat(n.contrasenia.length)),n))}}).catch(n=>{hideLoader(),console.log(n)})};n.initialLoad();n.contraseniaEncryp=function(n){n.contraseniaEncryp=n.contrasenia.replace(n.contrasenia,"*".repeat(n.contrasenia.length))};n.verContrasenia=function(n){n.contraseniaEncryp=n.contrasenia};n.post=function(){showLoader();let u=n.fileSign;if(!u){i.toastr("warning","Selecionele el archivo de la firma!");return}if(!n.firma.contrasenia){hideLoader();i.toastr("warning","Por favor ingrese la contraseña");return}if(!n.firma.fechaCaducidad){hideLoader();i.toastr("warning","Por seleccione la fecha caducidad");return}t.getDataFile(r+"Post/?json="+JSON.stringify(n.firma),u,null,!0).then(t=>{if(t.code==0){hideLoader();i.toastr("warning",t.message,t.titleSms);return}t.code==1&&(hideLoader(),i.toastr("success",t.message,t.titleSms),n.initialLoad(),$("#modalFirma").modal("hide"));hideLoader()}).catch(n=>{hideLoader(),console.log(n)})};n.put=function(){let f=n.fileSign;if(n.firma.estado){i.toastr("warning","Seleccione el archivo");return}let u={idFirmaElectronica:n.firma.idFirmaElectronica,contrasenia:n.firma.contrasenia,fechaCaducidad:n.firma.fechaCaducidad,estado:n.firma.estado};showLoader();t.getData("put",r+"Put/?json="+JSON.stringify(u),null,!0).then(function(t){if(hideLoader(),t.code==0){i.toastr("warning",t.message,t.titleSms);return}t.code==1&&(i.toastr("success",t.message,t.titleSms),n.initialLoad(),$("#modalUpdate").modal("hide"))}).catch(n=>{hideLoader(),console.log(n)})};n.updateSignature=async function(u){try{const{value:f}=await Swal.fire({title:"Seleccione el arhivo",input:"file",inputAttributes:{accept:".p12","aria-label":"Update Signature"},showCancelButton:!0,confirmButtonColor:"#3085d6",confirmButtonText:"Actualizar",cancelButtonText:"Cancelar"});if(!f)return;if(!(u.idFirmaElectronica>0)){i.toastr("warning","El id es:"+u.idFirmaElectronica);return}showLoader();t.getDataFile(r+"UpdateSignature/"+u.idFirmaElectronica,f,null,!0).then(function(t){if(hideLoader(),t.code==0){i.toastr("warning",t.message,t.titleSms);return}t.code==1&&(i.toastr("success",t.message,t.titleSms),n.initialLoad())}).catch(n=>{hideLoader(),console.log(n)})}catch(f){console.log(f)}};$("#modalFirma, #modalUpdate").on("hide.bs.modal",()=>{n.firma={},n.fileSign={}})}app.controller("firmaElectronicaCtrl",firmaElectronicaCtrl);firmaElectronicaCtrl.$inject=["$scope","mainService","toastService"];